package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClerkLimit {
    public void handle(@Parameter ClerkLimitException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.FORBIDDEN));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleClaimStatus {
    public void handle(@Parameter ClaimStatusException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: it starts DRAFT, is opened (OPEN) and then settled (SETTLED); a clerk settling one above the
 * clerk limit leaves it PENDING, which a steward approves (SETTLED) or rejects (back to OPEN). A DRAFT, OPEN or
 * PENDING claim can be voided (VOID). SETTLED and VOID are final. Only OPEN, PENDING and SETTLED claims count toward
 * totals.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The status an action ("open", "settle", "approve", "reject", "void") moves this one to, or null when it is not
     *  allowed. A settle above the clerk limit by a clerk ends in PENDING instead. */
    public ClaimStatus after(String action) {
        return switch (action) {
            case "open" -> this == DRAFT ? OPEN : null;
            case "settle" -> this == OPEN ? SETTLED : null;
            case "approve" -> this == PENDING ? SETTLED : null;
            case "reject" -> this == PENDING ? OPEN : null;
            case "void" -> this == DRAFT || this == OPEN || this == PENDING ? VOID : null;
            default -> null;
        };
    }

    /** Whether a claim in this status is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the
     *  totals). */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** The audit event recorded on entering this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Long id;
        try {
            id = Long.valueOf(personId.trim());
        } catch (NumberFormatException e) {
            throw new PersonNotFoundException(personId);
        }
        personOut.set(repository.findByIdAndSheetId(id, sheetId.trim())
                .orElseThrow(() -> new PersonNotFoundException(personId)));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the edited claim, once it is saved. */
public class AuditClaimEdited {
    public void audit(@Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("CLAIM_EDITED", claim, person, AuditUser.decode(user)));
    }
}
package net.officefloor.hq.app.statement;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.math.BigDecimal;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimFigures;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonGradeRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes a statement for the person: records their due-total now, on the sheet's today, and binds each of
